*/

.anv-navbar {
  display: flex;
  font-family: "Inter", Arial, sans-serif;
  background: #fff;
  position: relative;
  z-index: 1000;
}
/*
   MAIN CONTAINER
*/
.anv-stripes {
  width: 100%;
  background: #fff;
  border-bottom: 1px solid #e6e6e6;
  box-shadow: 0 2px 12px rgba(0,0,0,.05);
}

.anv-content {
  width: min(1350px, 100%);
  margin: auto;

  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-right: 20px;
  gap: 30px;

  padding: 18px clamp(50px,3vw,60px);
}

/*
   LOGO
*/

.anv-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.anv-brand-icon {
  width: clamp(60px,7vw,100px);
  height: auto;
  object-fit: contain;
  transition: .3s;
}

.anv-brand-icon:hover{
  transform: scale(1.08);
}

.anv-brand-name{
  font-size:22px;
  font-weight:700;
  color:#1f4d4a;
  white-space: nowrap;
}

/*
   NAVIGATION
*/

.anv-links{

  display:flex;
  justify-content:right;
  align-items:center;

  flex:1;

  gap:clamp(18px,3vw,40px);

  min-width:0;
}

.anv-link{

  position:relative;

  text-decoration:none;

  color:#555;

  font-size:17px;

  font-weight:600;

  transition:.3s;

  white-space:nowrap;
}

.anv-link:hover{

  color:#1f4d4a;
}

.anv-link::after{

  content:"";

  position:absolute;

  left:0;

  bottom:-8px;

  width:0;

  height:2px;

  background:#1f4d4a;

  transition:.3s;
}

.anv-link:hover::after{

  width:100%;
}

/*
   RIGHT SIDE
*/

.anv-actions{

  display:flex;

  align-items:center;

  gap:18px;

  flex-shrink:0;

  margin-left:auto;
}

.anv-icon-btn{

  width:42px;

  height:42px;

  display:flex;

  justify-content:center;

  align-items:center;

  border:none;

  background:none;

  cursor:pointer;

  transition:.3s;

  border-radius:50%;
}

.anv-icon-btn:hover{

  background:#f4f4f4;

  transform:translateY(-2px);
}

.anv-divider{

  width:1px;

  height:32px;

  background:#d8d8d8;
}

/*
   LOGIN BUTTON
*/

.anv-login-btn{

  padding:10px 24px;

  border:none;

  border-radius:30px;

  background:#1f4d4a;

  color:#fff;

  font-size:15px;

  font-weight:600;

  cursor:pointer;

  transition:.3s;
}

.anv-login-btn:hover{

  background:#163836;

  transform:translateY(-2px);

  box-shadow:0 8px 18px rgba(0,0,0,.18);
}

.anv-login-btn:active{

  transform:scale(.96);
}

/*
   PROFILE
*/

.anv-profile-wrap{

  position:relative;
}

.anv-profile-btn{

  width:48px;

  height:48px;

  border:none;

  border-radius:50%;

  background:#111;

  color:#fff;

  cursor:pointer;

  display:flex;

  justify-content:center;

  align-items:center;

  transition:.3s;
}

.anv-profile-btn:hover{

  transform:scale(1.08);

  box-shadow:0 8px 18px rgba(0,0,0,.15);
}

/*
   DROPDOWN
*/

.anv-dropdown{

  position:absolute;

  top:calc(100% + 12px);

  right:0;

  width:260px;

  background:#fff;

  border-radius:14px;

  box-shadow:0 12px 30px rgba(0,0,0,.18);

  overflow:hidden;

  animation:dropdown .25s ease;

  z-index:999;
}

@keyframes dropdown{

from{

opacity:0;

transform:translateY(-10px);

}

to{

opacity:1;

transform:translateY(0);

}

}

.anv-dropdown-header{

display:flex;

align-items:center;

gap:12px;

padding:16px;
}

.anv-dropdown-avatar{

width:45px;

height:45px;

